import {ToolRegistry} from './registry.js';
import type {ToolResponse} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property and does not call executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn().mockResolvedValue('success');

    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
          },
          required: ['location'],
        },
      },
      executor
    );

    const result = (await registry.execute('test_tool', {})) as ToolResponse;

    expect({
      called: executor.mock.calls.length,
      hasLocation: /location/i.test(result.result),
      hasRequired: /required/i.test(result.result),
    }).toEqual({
      called: 0,
      hasLocation: true,
      hasRequired: true,
    });
  });
});
